            int po=get<0>(kv.first), px=get<1>(kv.first); long long mask=get<2>(kv.first); int turn=get<3>(kv.first);
            int mn=min(po,px), mx=max(po,px);
            vector<long long> s; s.push_back(po); s.push_back(px); s.push_back(turn);
