            if(variant>=4){ s.push_back(bitsRange(mask, mn+4, mx-4)); }
            auto it=sig.find(s);
            if(it==sig.end()) sig[s]=kv.second;
            else if(it->second!=kv.second) collisions++;
        }
        printf("variant %d: collisions=%lld states=%zu sigs=%zu\n", variant, collisions, memo.size(), sig.size());
    }
