    if(mode==0){ for(int i=3;i<=n;i++) a[i]=rng()%100+1; }
    else if(mode==1){ for(int i=3;i<=n;i++) a[i]=1; }
    else if(mode==2){ for(int i=3;i<=n;i++) a[i]= (long long)pow(3.0,(i-3)%7); }
    else { for(int i=3;i<=n;i++) a[i]=1; if(n>=3) a[rng()%(n-2)+3]=1000000; }
    a[1]=a[2]=0;
    memo.clear();
    solve(1,2,6,0);
    map<vector<long long>,long long> sig;
    long long collisions=0;
    for(auto &kv: memo){
        int po=get<0>(kv.first), px=get<1>(kv.first); long long mask=get<2>(kv.first); int turn=get<3>(kv.first);
        int mx=max(po,px);
        vector<long long> s{po,px,turn,bitsRange(mask,mx-3,mx)};
        auto it=sig.find(s);
        if(it==sig.end()) sig[s]=kv.second;
        else if(it->second!=kv.second) collisions++;
    }
    return (int)collisions;
}
int main(){
    mt19937 rng(2024);
    for(int nn=8; nn<=16; nn+=2){
        int c0=check(nn,0,rng);
        int c2=check(nn,2,rng);
        int c3=check(nn,3,rng);
        printf("n=%d random_coll=%d pow_coll=%d onebig_coll=%d\n", nn, c0,c2,c3);
        fflush(stdout);
    }
}

#include <bits/stdc++.h>
using namespace std;
int n; long long a[60];
map<tuple<int,int,long long,int>,long long> memo;
long long solve(int po,int px,long long mask,int turn){
    auto key=make_tuple(po,px,mask,turn);
    auto it=memo.find(key);
    if(it!=memo.end()) return it->second;
    int pos = turn==0?po:px;
    bool moved=false;
    long long best = (turn==0?LLONG_MIN:LLONG_MAX);
    for(int d=1;d<=4;d++){
        int np=pos+d; if(np>n) break;
        if(mask>>np&1) continue;
        moved=true;
        long long v;
        if(turn==0) v=a[np]+solve(np,px,mask|(1LL<<np),1);
        else v=-a[np]+solve(po,np,mask|(1LL<<np),0);
        if(turn==0) best=max(best,v); else best=min(best,v);
    }
    if(!moved){
        int other=turn==0?px:po;
        bool st=true;
        for(int d=1;d<=4;d++){int np=other+d; if(np<=n && !(mask>>np&1)){st=false;break;}}
        best = st?0:solve(po,px,mask,1-turn);
    }
    memo[key]=best; return best;
}
long long bitsRange(long long mask,int lo,int hi){
    long long r=0; int k=0;
    for(int c=lo;c<=hi;c++){ if(c>=1&&c<=n && (mask>>c&1)) r|=1LL<<k; k++; }
    return r;
}
