#include <bits/stdc++.h>
using namespace std;
int n; long long a[60];
map<tuple<int,int,long long,int>,long long> memo;
map<tuple<int,int,long long,int>,int> bd;
long long solve(int po,int px,long long mask,int turn){
    auto key=make_tuple(po,px,mask,turn);
    auto it=memo.find(key);
    if(it!=memo.end()) return it->second;
    int pos = turn==0?po:px;
    bool moved=false;
    long long best = (turn==0?LLONG_MIN:LLONG_MAX);
    int bestd=-1;
    for(int d=1;d<=4;d++){
        int np=pos+d; if(np>n) break;
        if(mask>>np&1) continue;
        moved=true;
        long long v;
        if(turn==0) v=a[np]+solve(np,px,mask|(1LL<<np),1);
        else v=-a[np]+solve(po,np,mask|(1LL<<np),0);
        if(turn==0){ if(v>best){best=v;bestd=d;} }
        else { if(v<best){best=v;bestd=d;} }
    }
    if(!moved){
        int other=turn==0?px:po;
        bool st=true;
        for(int d=1;d<=4;d++){int np=other+d; if(np<=n && !(mask>>np&1)){st=false;break;}}
        best = st?0:solve(po,px,mask,1-turn);
        bestd=0;
    }
    memo[key]=best; bd[key]=bestd; return best;
}
int main(){
    mt19937 rng(555);
    for(int nn=10; nn<=20; nn+=2){
        n=nn;
        for(int i=3;i<=n;i++) a[i]=rng()%100+1;
        a[1]=a[2]=0;
        memo.clear(); bd.clear();
        long long v=solve(1,2,6,0);
        int po=1,px=2; long long mask=6; int turn=0; int maxgap=0; int steps=0;
        while(steps<50){
            int pos=turn==0?po:px;
            auto key=make_tuple(po,px,mask,turn);
            int d=bd[key];
            int other=turn==0?px:po;
            bool can=false;
            for(int dd=1;dd<=4;dd++){int np=pos+dd; if(np<=n && !(mask>>np&1)){can=true;break;}}
            if(!can){ turn=1-turn; steps++; continue; }
            int np=pos+d; mask|=1LL<<np;
            if(turn==0) po=np; else px=np;
            maxgap=max(maxgap,abs(po-px));
            turn=1-turn; steps++;
            if(steps>40) break;
        }
        printf("n=%d value=%lld maxgap_in_optline=%d\n", n, v, maxgap);
        fflush(stdout);
    }
}

