// simplified: ignore history, only can't land on other's current pos
map<tuple<int,int,int>,long long> memo2;
long long solve2(int po,int px,int turn){
    auto key=make_tuple(po,px,turn);
    auto it=memo2.find(key);
    if(it!=memo2.end()) return it->second;
    int pos = turn==0?po:px;
    int other = turn==0?px:po;
    bool moved=false;
    long long best = (turn==0?LLONG_MIN:LLONG_MAX);
    for(int d=1;d<=4;d++){
        int np=pos+d; if(np>n) break;
        if(np==other) continue;
        moved=true;
        long long v;
        if(turn==0) v=a[np]+solve2(np,px,1);
        else v=-a[np]+solve2(po,np,0);
        if(turn==0) best=max(best,v); else best=min(best,v);
    }
    if(!moved){
        bool st=true;
        for(int d=1;d<=4;d++){int np=other+d; if(np<=n && np!=pos){st=false;break;}}
        best = st?0:solve2(po,px,1-turn);
    }
    memo2[key]=best; return best;
}
